+
+<div class="d-flex align-items-center gap-3 mb-3">
+    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
+    <button class="btn btn-danger" @onclick="Clear">Clear</button>
+    @if (lastSavedAt is not null)
+    {
+        <span class="text-muted">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
+    }
+</div>
+
+@code {
+    private string content = string.Empty;
+    private DateTime? lastSavedAt;
+    private bool hasUnsavedChanges;
+    private Timer? autoSaveTimer;
+    private IJSObjectReference? jsModule;
+
+    private const string StorageKey = "notepad-content";
+    private const string TimestampKey = "notepad-last-saved";
+
+    protected override async Task OnAfterRenderAsync(bool firstRender)
+    {
+        if (firstRender)
+        {
+            jsModule = await JS.InvokeAsync<IJSObjectReference>("import", "./Components/Pages/Notepad.razor.js");
+
+            var saved = await jsModule.InvokeAsync<string?>("load", StorageKey);
+            if (!string.IsNullOrEmpty(saved))
+            {
+                content = saved;
+            }
+
+            var savedTimestamp = await jsModule.InvokeAsync<string?>("load", TimestampKey);
+            if (DateTime.TryParse(savedTimestamp, out var ts))
+            {
+                lastSavedAt = ts;
+            }
+
+            autoSaveTimer = new Timer(AutoSaveCallback, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
+
+            StateHasChanged();
+        }
+    }
+
+    private void OnContentChanged()
+    {
+        hasUnsavedChanges = true;
+        _ = UpdateBeforeUnload(true);
+    }
+
+    private async Task SaveNow()
+    {
+        await Save();
+    }
+
+    private async Task Save()
+    {
+        if (jsModule is null) return;
+
+        await jsModule.InvokeVoidAsync("save", StorageKey, content);
+        lastSavedAt = DateTime.Now;
+        await jsModule.InvokeVoidAsync("save", TimestampKey, lastSavedAt.Value.ToString("o"));
+        hasUnsavedChanges = false;
+        await UpdateBeforeUnload(false);
+    }
+
+    private async void AutoSaveCallback(object? state)
+    {
+        await InvokeAsync(async () =>
+        {
+            await Save();
+            StateHasChanged();
+        });
+    }
+
+    private async Task Clear()
+    {
+        if (jsModule is null) return;
+
+        content = string.Empty;
+        lastSavedAt = null;
+        hasUnsavedChanges = false;
+        await jsModule.InvokeVoidAsync("remove", StorageKey);
+        await jsModule.InvokeVoidAsync("remove", TimestampKey);
+        await UpdateBeforeUnload(false);
+    }
+
+    private async Task UpdateBeforeUnload(bool enabled)
+    {
+        if (jsModule is not null)
+        {
+            await jsModule.InvokeVoidAsync("setBeforeUnload", enabled);
+        }
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        autoSaveTimer?.Dispose();
+        if (jsModule is not null)
+        {
+            await jsModule.InvokeVoidAsync("setBeforeUnload", false);
+            await jsModule.DisposeAsync();
+        }
+    }
